def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    # Adjacent pairs on the top and bottom edges launch inward rays.
    pairs = []
    for r, dr in ((0, 1), (h - 1, -1)):
        for c in range(w - 1):
            if grid[r][c] == grid[r][c + 1] != bg:
                pairs.append((r, c, dr, grid[r][c]))

    if pairs:
        marker_colors = {p[3] for p in pairs}
        source_colors = [v for v in counts if v != bg and v not in marker_colors]
        if source_colors:
            source = min(source_colors, key=lambda v: counts[v])
            for r, c, dr, _ in pairs:
                rr = r + dr
                while 0 <= rr < h:
                    if grid[rr][c] == source:
                        out[rr][c] = 4
                        break
                    if grid[rr][c] == bg:
                        out[rr][c] = source
                    rr += dr
            return out

    # Vertical edge segments act as reflectors for horizontal rays.
    for wall in counts:
        if wall == bg:
            continue

        def edge_runs(col):
            runs = []
            r = 0
            while r < h:
                if grid[r][col] == wall:
                    start = r
                    while r < h and grid[r][col] == wall:
                        r += 1
                    runs.append((start, r))
                else:
                    r += 1
            return runs

        left_runs, right_runs = edge_runs(0), edge_runs(w - 1)
        for ls, le in left_runs:
            for rs, re in right_runs:
                if le - ls != re - rs or le - ls < 2:
                    continue
                for r in range(rs, re):
                    for c in range(w):
                        v = grid[r][c]
                        if v == bg or v == wall:
                            continue
                        out[r][c] = 4
                        # Ray from the source toward the right-hand wall.
                        cc = c + 1
                        while cc < w and grid[r][cc] != wall:
                            if grid[r][cc] == bg:
                                out[r][cc] = v
                            cc += 1
                        # Reflected ray across the matching left segment.
                        rr = ls + (r - rs)
                        for cc in range(1, w):
                            if grid[rr][cc] == bg:
                                out[rr][cc] = v
                return out

    return out
